def solve(input_data):
    coins = input_data["coins"]
    amount = input_data["amount"]
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] <= amount else -1

def solve(input_data):
    coins = input_data["coins"]
    amount = input_data["amount"]
    if amount == 0:
        return 0
    from collections import deque
    q = deque([(0, 0)])
    visited = {0}
    while q:
        cur, steps = q.popleft()
        for coin in coins:
            nxt = cur + coin
            if nxt == amount:
                return steps + 1
            if nxt < amount and nxt not in visited:
                visited.add(nxt)
                q.append((nxt, steps + 1))
    return -1

