def trace(input_data):
    sess = TraceSession(
        algorithm="Coin Change BFS",
        input_data=input_data,
        pseudocode=[
            "Start from amount 0 with steps 0",
            "While queue not empty:",
            "  Pop (cur, steps) from queue",
            "  For each coin: next = cur + coin",
            "    If next == amount: return steps+1",
            "    If next < amount and unvisited: mark visited, enqueue"
        ]
    )
    coins = input_data["coins"]
    amount = input_data["amount"]
    if amount == 0:
        sess.result(0)
        return sess.to_trace()
    visited = {0}
    queue = __import__('collections').deque([0])
    steps = {0: 0}
    ans = -1
    with sess.step("Initial state"):
        sess.note("Start BFS from 0 with steps 0")
    while queue:
        cur = queue.popleft()
        cur_steps = steps[cur]
        with sess.step(f"Explore amount {cur}"):
            for coin in coins:
                nxt = cur + coin
                if nxt == amount:
                    ans = cur_steps + 1
                    sess.note(f"Reached target with {ans} coins")
                    break
                if nxt < amount and nxt not in visited:
                    visited.add(nxt)
                    queue.append(nxt)
                    steps[nxt] = cur_steps + 1
                    sess.note(f"Enqueue {nxt} with steps {cur_steps+1}")
            if ans != -1:
                break
    sess.result(ans)
    return sess.to_trace()
